package ro.leo.visual;
import android.content.*;import android.graphics.*;import android.os.*;import android.text.InputType;import android.view.*;import android.widget.*;import java.util.*;
/** Native keypad FM tuner; signal display uses receiver measurements, no simulated animation. */
public final class FmActivity extends LeoActivity {
    private int selected=101300;private TextView frequency,status,level,station,rdsText;private Dial dial;private final Handler handler=new Handler();private boolean page;
    private final BroadcastReceiver changes=new BroadcastReceiver(){public void onReceive(Context c,Intent i){if(page){selected=FmService.frequency;update();}}};
    protected void onCreate(Bundle state){super.onCreate(state);FmService.loadStations(this);selected=FmService.instance==null?getSharedPreferences("fm",0).getInt("frequency",101300):FmService.frequency;show();}
    protected void onResume(){super.onResume();registerReceiver(changes,new IntentFilter(FmService.CHANGED));update();}
    protected void onPause(){unregisterReceiver(changes);super.onPause();}
    protected void onDestroy(){handler.removeCallbacksAndMessages(null);super.onDestroy();}
    private void show(){page=true;begin("Radio FM Leo");status=text("",15);status.setGravity(Gravity.CENTER);root.addView(status);frequency=text("",44);frequency.setTypeface(Typeface.create("sans-serif-condensed",Typeface.BOLD));frequency.setGravity(Gravity.CENTER);root.addView(frequency);station=text("",18);station.setGravity(Gravity.CENTER);station.setSingleLine(true);root.addView(station);rdsText=text("",12);rdsText.setGravity(Gravity.CENTER);rdsText.setMaxLines(2);root.addView(rdsText);dial=new Dial();root.addView(dial,new LinearLayout.LayoutParams(-1,0,1));level=text("",14);level.setGravity(Gravity.CENTER);root.addView(level);root.addView(text("◀ ▶ acordaj   ▲ ▼ volum",13));left=new Runnable(){public void run(){menu();}};footer("Opțiuni","Redare","Înapoi");update();}
    private void update(){if(!page||frequency==null)return;frequency.setText(String.format(Locale.ROOT,"%.1f MHz",selected/1000f));status.setText(FmService.starting||FmService.playing?FmService.state:FmService.wired(this)?"Căști conectate · "+FmService.state:"Conectează căștile cu fir");int vol=FmService.instance==null?getSharedPreferences("fm",0).getInt("volume",8):FmService.volume;level.setText("Volum "+vol+"% · "+(FmService.playing?(FmService.signal==-128?"RSSI —":"RSSI "+FmService.signal):"87,5–108 MHz"));station.setText(FmService.stationName.isEmpty()?"RDS · fără nume recepționat":FmService.stationName);rdsText.setText(FmService.radioText);dial.invalidate();}
    private void tune(int khz){if(FmService.scanning||FmService.seeking){selected=FmService.frequency;update();notice("Așteaptă terminarea căutării sau oprește radioul");return;}selected=khz<87500?108000:khz>108000?87500:khz;FmService current=FmService.instance;if(current!=null)current.tune(selected);else{FmService.frequency=selected;getSharedPreferences("fm",0).edit().putInt("frequency",selected).apply();}update();}
    private void toggle(){startService(new Intent(this,FmService.class).setAction(FmService.playing||FmService.starting?"stop":"start"));}
    private void volume(int delta){int value=Math.max(0,Math.min(100,(FmService.instance==null?getSharedPreferences("fm",0).getInt("volume",8):FmService.volume)+delta));if(FmService.instance!=null)FmService.instance.setVolume(value);else{FmService.volume=value;getSharedPreferences("fm",0).edit().putInt("volume",value).apply();}update();}
    private void saveFavorite(int khz){Set<String> saved=new HashSet<String>(getSharedPreferences("fm",0).getStringSet("favorites",Collections.<String>emptySet()));if(saved.size()>=8&&!saved.contains(""+khz)){notice("Maximum 8 favorite");return;}saved.add(""+khz);getSharedPreferences("fm",0).edit().putStringSet("favorites",saved).apply();notice("Frecvență salvată");}
    private void menu(){options("Radio FM",new String[]{FmService.playing||FmService.starting?"Oprește":"Pornește","Canale scanate · "+FmService.stations.size(),FmService.scanning?"Scanare în curs…":"Scanează banda","Favorite","Salvează frecvența",FmService.speaker?"Ascultă în căști":"Activează difuzorul","Frecvență directă","Postul următor ▶","◀ Postul anterior","Despre radio"},new Choice(){public void pick(int i){if(i==0)toggle();else if(i==1)channels();else if(i==2){if(FmService.instance==null||!FmService.playing){notice("Pornește întâi radioul");return;}FmService.instance.scan();}else if(i==3)favorites();else if(i==4)saveFavorite(selected);else if(i==5){if(FmService.instance==null||!FmService.playing)notice("Pornește întâi radioul");else FmService.instance.setSpeaker(!FmService.speaker);}else if(i==6)direct();else if(i==7||i==8){if(FmService.instance==null||!FmService.playing)notice("Pornește întâi radioul");else FmService.instance.seek(i==7);}else notice("Căștile rămân antena și la redarea pe difuzor. Scanarea salvează vârfuri de semnal; unele pot fi slabe sau zgomotoase. Se oprește la apel, alt sunet sau scoaterea căștilor. Sesiunea este limitată la o oră; poți porni din nou.");}});}
    private void channels(){page=false;final ArrayList<Integer> values=new ArrayList<Integer>(FmService.stations.keySet());ArrayList<String> labels=new ArrayList<String>();for(int khz:values)labels.add(String.format(Locale.ROOT,"%.1f MHz · RSSI %d",khz/1000f,FmService.stations.get(khz)));list("Canale scanate · "+values.size(),labels,0,new Choice(){public void pick(final int i){options(String.format(Locale.ROOT,"%.1f MHz",values.get(i)/1000f),new String[]{"Ascultă","Adaugă la favorite"},new Choice(){public void pick(int action){if(action==1)saveFavorite(values.get(i));else{selected=values.get(i);show();tune(selected);if(!FmService.playing&&!FmService.starting)toggle();}}});}},"",null);back=new Runnable(){public void run(){show();}};}
    private void favorites(){final ArrayList<Integer> saved=new ArrayList<Integer>();for(String value:getSharedPreferences("fm",0).getStringSet("favorites",Collections.<String>emptySet()))try{int khz=Integer.parseInt(value);if(khz>=87500&&khz<=108000)saved.add(khz);}catch(NumberFormatException ignored){}Collections.sort(saved);ArrayList<String> labels=new ArrayList<String>();for(int value:saved)labels.add(String.format(Locale.ROOT,"%.1f MHz",value/1000f));page=false;list("Favorite FM",labels,0,new Choice(){public void pick(final int i){options(labels.get(i),new String[]{"Acordează","Elimină favoritul"},new Choice(){public void pick(int action){if(action==0){selected=saved.get(i);show();tune(selected);}else{Set<String> values=new HashSet<String>(getSharedPreferences("fm",0).getStringSet("favorites",Collections.<String>emptySet()));values.remove(""+saved.get(i));getSharedPreferences("fm",0).edit().putStringSet("favorites",values).apply();favorites();}}});}},"",null);back=new Runnable(){public void run(){show();}};}
    private void direct(){page=false;LinearLayout panel=fields("Frecvență FM");final EditText field=field(panel,"MHz · exemplu 101.3",String.format(Locale.ROOT,"%.1f",selected/1000f),InputType.TYPE_CLASS_NUMBER|InputType.TYPE_NUMBER_FLAG_DECIMAL);left=new Runnable(){public void run(){try{float mhz=Float.parseFloat(field.getText().toString().replace(',','.'));int khz=Math.round(mhz*10)*100;if(!Float.isFinite(mhz)||khz<87500||khz>108000)throw new NumberFormatException();show();tune(khz);}catch(NumberFormatException e){notice("Alege 87,5–108,0 MHz");}}};back=new Runnable(){public void run(){show();}};footer("Acordează","Editor","Șterge");field.requestFocus();}
    public boolean onKeyDown(int key,KeyEvent event){if(page){if((FmService.scanning||FmService.seeking)&&(key==KeyEvent.KEYCODE_DPAD_LEFT||key==KeyEvent.KEYCODE_DPAD_RIGHT))return true;if(key==KeyEvent.KEYCODE_DPAD_LEFT||key==KeyEvent.KEYCODE_DPAD_RIGHT){tune(selected+(key==KeyEvent.KEYCODE_DPAD_LEFT?-100:100));return true;}if(key==KeyEvent.KEYCODE_DPAD_UP||key==KeyEvent.KEYCODE_DPAD_DOWN){volume(key==KeyEvent.KEYCODE_DPAD_UP?2:-2);return true;}if(key==KeyEvent.KEYCODE_DPAD_CENTER||key==KeyEvent.KEYCODE_ENTER){if(event.getRepeatCount()==0)toggle();return true;}}return super.onKeyDown(key,event);}
    private final class Dial extends View {private final Paint pen=new Paint(Paint.ANTI_ALIAS_FLAG);Dial(){super(FmActivity.this);}protected void onDraw(Canvas c){float w=getWidth(),h=getHeight(),mid=w/2;pen.setColor(palette.card);c.drawRoundRect(10,3,w-10,h-3,16,16,pen);pen.setStrokeWidth(dp(1));for(int n=-10;n<=10;n++){float x=mid+n*w/24;int khz=selected+n*100;if(khz<87500||khz>108000)continue;pen.setColor(n==0?palette.accent:0x77ffffff);c.drawLine(x,h*.18f,x,h*(n%5==0?.58f:.42f),pen);}pen.setColor(palette.accent);pen.setStrokeWidth(dp(3));c.drawLine(mid,h*.1f,mid,h*.64f,pen);int bars=FmService.playing&&!FmService.scanning?Math.max(0,Math.min(12,(FmService.signal+110)*12/70)):0;for(int n=0;n<12;n++){pen.setColor(n<bars?palette.accent:0x22ffffff);float x=18+n*(w-36)/12;c.drawRect(x,h*.78f,x+(w-36)/12-3,h*.9f,pen);}}}
}
